function VibeDatePicker({value,onChange,language='en',maxDate=''}) {
 const [open,setOpen]=useState(false);
 const [month,setMonth]=useState(()=>{const d=value?new Date(value+'T12:00:00'):new Date();return new Date(d.getFullYear(),d.getMonth(),1)});
 const names=language==='ru'?['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь']:language==='de'?['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember']:['January','February','March','April','May','June','July','August','September','October','November','December'];
 const weekdays=language==='ru'?['Пн','Вт','Ср','Чт','Пт','Сб','Вс']:language==='de'?['Mo','Di','Mi','Do','Fr','Sa','So']:['Mo','Tu','We','Th','Fr','Sa','Su'];
 const chosen=value?new Date(value+'T12:00:00'):null;
 const first=new Date(month.getFullYear(),month.getMonth(),1);
 const offset=(first.getDay()+6)%7;
 const days=Array.from({length:42},(_,i)=>new Date(month.getFullYear(),month.getMonth(),i-offset+1));
 const today=new Date();today.setHours(0,0,0,0);
 const max=maxDate?new Date(maxDate+'T00:00:00'):today;
 const fmt=(d)=>String(d.getFullYear())+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
 const display=chosen&&!Number.isNaN(chosen.getTime())?chosen.toLocaleDateString(language==='ru'?'ru-RU':language==='de'?'de-DE':'en-GB',{day:'numeric',month:'long',year:'numeric'}):(language==='ru'?'Выбрать дату':language==='de'?'Datum auswählen':'Choose date');
 return <div className="vibe-date-picker">
  <button type="button" className={'vibe-date-trigger'+(open?' is-open':'')} onClick={()=>{if(!open&&value){const d=new Date(value+'T12:00:00');setMonth(new Date(d.getFullYear(),d.getMonth(),1))}setOpen(v=>!v)} } aria-haspopup="dialog" aria-expanded={open}><span className="vibe-date-icon"><span/></span><span className={value?'':'vibe-date-placeholder'}>{display}</span><span className="vibe-date-trigger-caret">⌄</span></button>
  {open&&<div className="vibe-calendar-popover" role="dialog" aria-label={language==='ru'?'Выбор даты':language==='de'?'Datum auswählen':'Choose a date'}>
   <div className="vibe-calendar-top"><div><small>{language==='ru'?'ВЫБОР ДАТЫ':language==='de'?'DATUM WÄHLEN':'SELECT DATE'}</small><b>{chosen&&!Number.isNaN(chosen.getTime())?chosen.toLocaleDateString(language==='ru'?'ru-RU':language==='de'?'de-DE':'en-GB',{day:'numeric',month:'short'}):(language==='ru'?'Дата рождения':language==='de'?'Geburtsdatum':'Date of birth')}</b></div><span className="vibe-calendar-orb">✦</span></div>
   <div className="vibe-calendar-month"><button type="button" aria-label="Previous month" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}><ArrowLeft size={16}/></button><b>{names[month.getMonth()]} {month.getFullYear()}</b><button type="button" aria-label="Next month" disabled={month.getFullYear()===max.getFullYear()&&month.getMonth()>=max.getMonth()} onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><ArrowRight size={16}/></button></div>
   <div className="vibe-calendar-grid vibe-calendar-weekdays">{weekdays.map(d=><span key={d}>{d}</span>)}</div>
   <div className="vibe-calendar-grid">{days.map((d,i)=>{const key=fmt(d),same=d.getMonth()===month.getMonth(),active=value===key,disabled=d>max;return <button type="button" key={i} disabled={disabled} className={['vibe-calendar-day',same?'':'is-outside',active?'is-selected':'',fmt(d)===fmt(today)?'is-today':''].filter(Boolean).join(' ')} onClick={()=>{onChange(key);setOpen(false)}}>{d.getDate()}</button>})}</div>
   <div className="vibe-calendar-bottom"><span>{language==='ru'?'Выбери свой день рождения':language==='de'?'Wähle deinen Geburtstag':'Pick your birthday'}</span><button type="button" onClick={()=>{onChange('');setOpen(false)}}>{language==='ru'?'Очистить':language==='de'?'Löschen':'Clear'}</button></div>
  </div>}
 </div>;
}

