 const boot=useCallback(async()=>{if(!initData&&!webSession){setLoading(false);return}setLoading(true);setError('');try{if(initData){await call('/api/auth/telegram',{method:'POST',body:JSON.stringify({initData})})}const me=await call('/api/me');setUser(me.user);const u=me.user;setProfile({birthDate:u.birth_date?String(u.birth_date).slice(0,10):'',gender:u.gender||'',bio:u.bio||'',city:u.city||'',photoUrl:u.photo_url||'',goal:u.goal||'both',interests:Array.isArray(u.interests)?u.interests:[]});if(!u.birth_date||!String(u.city||'').trim())setProfileOpen(true);await refresh()}catch(e){if(!initData&&webSession&&e.status===401){try{localStorage.removeItem('vibe-session')}catch{}setWebSession('');setUser(null);setAuthError('Сессия завершилась. Войди снова.')}setError(e.message)}finally{setLoading(false)}},[call,refresh,webSession]);
 useEffect(()=>{boot()},[boot]);useEffect(()=>{try{localStorage.setItem('vibe-language',language);localStorage.setItem('vibe-settings',JSON.stringify(settingsPrefs))}catch{}document.documentElement.classList.toggle('reduce-motion',Boolean(settingsPrefs.reduceMotion))},[language,settingsPrefs]);useEffect(()=>observeUiTranslations(language),[language]);useEffect(()=>{msgEnd.current?.scrollIntoView({behavior:'smooth'})},[messages]);useEffect(()=>{if(!initData&&!webSession)return;call('/api/stories').then(d=>setStories(d.stories||[])).catch(()=>{})},[call,webSession]);
 const filtered=useMemo(()=>people.filter(p=>{const q=search.trim().toLowerCase();return (!q||[p.name,p.city,p.country,p.description,p.hobbies,...(p.interests||[])].filter(Boolean).join(' ').toLowerCase().includes(q))&&(!cityFilter||p.city?.toLowerCase()===cityFilter.toLowerCase())}),[people,search,cityFilter]);
