function AuthGate({language,setLanguage,email,setEmail,code,setCode,step,setStep,busy,error,message,onRequestCode,onVerifyCode}){
 const tr=(ru,en,de)=>language==='ru'?ru:language==='de'?de:en;
 return <main className="auth-screen"><header className="auth-top"><a className="wordmark" href="/"><span className="vibe-mark">v.</span><span>vibe<span className="pink">.</span></span></a><select value={language} onChange={e=>setLanguage(e.target.value)} aria-label={tr('Язык','Language','Sprache')}><option value="ru">Русский</option><option value="en">English</option><option value="de">Deutsch</option></select></header><section className="auth-card"><div className="auth-orb auth-orb-one"/><div className="auth-orb auth-orb-two"/><div className="auth-brand-icon"><span className="vibe-mark">v.</span></div><span className="eyebrow">{tr('ТВОИ ЛЮДИ. ТВОЙ РИТМ.','YOUR PEOPLE. YOUR RHYTHM.','DEINE LEUTE. DEIN RHYTHMUS.')}</span><h1>{tr('Войди в VIBE','Sign in to VIBE','Bei VIBE anmelden')}</h1><p className="auth-intro">{tr('Находи людей по интересам и знакомься в своём ритме.','Meet people who share your interests at your own pace.','Finde Menschen mit ähnlichen Interessen und lerne neue Leute kennen.')}</p>{step==='email'?<form className="auth-form" onSubmit={onRequestCode}><label>{tr('Электронная почта','Email address','E-Mail-Adresse')}<input type="email" autoComplete="email" required maxLength={254} value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><button className="primary-button wide" disabled={busy||!email.trim()}>{busy?tr('Отправляем код…','Sending code…','Code wird gesendet…'):tr('Получить код','Send me a code','Code senden')} <ArrowRight size={17}/></button></form>:<form className="auth-form" onSubmit={onVerifyCode}><p className="auth-code-help">{tr('Введи шестизначный код, отправленный на','Enter the six-digit code sent to','Gib den sechsstelligen Code ein, der gesendet wurde an')} <b>{email}</b></p><label>{tr('Код из письма','Email code','E-Mail-Code')}<input type="text" inputMode="numeric" autoComplete="one-time-code" required pattern="[0-9]{6}" maxLength={6} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="000000"/></label><button className="primary-button wide" disabled={busy||code.length!==6}>{busy?tr('Проверяем…','Verifying…','Wird geprüft…'):tr('Войти в VIBE','Sign in to VIBE','Bei VIBE anmelden')} <ArrowRight size={17}/></button><button type="button" className="auth-text-button" onClick={()=>{setStep('email');setCode('')}}>{tr('Изменить адрес почты','Change email address','E-Mail-Adresse ändern')}</button></form>}{error&&<p className="auth-message auth-error" role="alert">{error}</p>}{message&&<p className="auth-message" role="status">{message}</p>}<p className="auth-legal">{tr('Продолжая, ты подтверждаешь, что соблюдаешь правила VIBE. Минимальный возраст — 14 лет.','By continuing, you agree to follow VIBE rules. Minimum age: 14.','Wenn du fortfährst, akzeptierst du die VIBE-Regeln. Mindestalter: 14 Jahre.')}</p><div className="auth-divider auth-telegram-divider"><span>{tr('или','or','oder')}</span></div><a className="auth-telegram-button" href="https://t.me/iBEDatig_Bot" onClick={e=>{if(tg?.openTelegramLink){e.preventDefault();tg.openTelegramLink('https://t.me/iBEDatig_Bot')}}}><Send size={16}/>{tr('Войти через Telegram','Continue with Telegram','Mit Telegram fortfahren')} <ArrowRight size={16}/></a></section><footer className="auth-footer">vibe. © 2026 <span>{tr('Твои люди. Твой ритм.','Your people. Your rhythm.','Deine Leute. Dein Rhythmus.')}</span><a className="support-email-link" href="mailto:vibesupport2026@gmail.com">{tr('Поддержка','Support','Support')}: vibesupport2026@gmail.com</a></footer></main>
}

function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function PageTitle({kicker,title,subtitle}){return <div className="page-heading compact"><div><span className="eyebrow">{kicker}</span><h1>{title}</h1><p>{subtitle}</p></div></div>}
function Empty({icon:Icon,title,text}){return <div className="empty-state"><span className="empty-symbol"><Icon size={23}/></span><h3>{title}</h3><p>{text}</p></div>}
function CompactPerson({person,onOpen,action}){return <article className="compact-person"><span className="avatar large">{person.photo_url?<img src={person.photo_url} alt=""/>:(person.name||'V')[0]}</span><b>{person.name||'Участник'}</b><small><MapPin size={12}/>{person.city||'VIBE'}</small><button className="primary-button" onClick={onOpen}><MessageCircle size={15}/>{action}</button></article>}
function Landing({language,setLanguage}){const t=(ru,en,de)=>language==='ru'?ru:language==='de'?de:en;return <main className="landing"><header className="landing-header"><a className="wordmark" href="#"><span className="vibe-mark">v.</span><span>vibe<span className="pink">.</span></span></a><select value={language} onChange={e=>setLanguage(e.target.value)} aria-label={t('Язык','Language','Sprache')}><option value="ru">Русский</option><option value="en">English</option><option value="de">Deutsch</option></select></header><section className="landing-hero"><div className="landing-copy"><span className="eyebrow"><Sparkles size={14}/> YOUR PEOPLE. YOUR RHYTHM.</span><h1>{t('Найди людей, с которыми','Find people who','Finde Menschen, die')}<br/><span>{t('совпадает вайб.','match your vibe.','zu deinem Vibe passen.')}</span></h1><p>{t('Знакомься, делись интересами и начинай настоящие разговоры — в своём ритме.','Meet people, share interests and start real conversations at your own pace.','Lerne Menschen kennen, teile Interessen und beginne echte Gespräche in deinem Tempo.')}</p><a className="primary-button register-link" href="https://t.me/iBEDatig_Bot" onClick={()=>tg?.openTelegramLink?.('https://t.me/iBEDatig_Bot')}><LogIn size={18}/>{t('Открыть VIBE в Telegram','Open VIBE in Telegram','VIBE in Telegram öffnen')} <ArrowRight size={17}/></a><div className="landing-notes"><span><CheckCircle2 size={15}/> {t('Анкеты проходят проверку','Reviewed profiles','Profile werden geprüft')}</span><span><Lock size={15}/> {t('Безопасность прежде всего','Safety first','Sicherheit zuerst')}</span></div></div><div className="landing-art"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="demo-profile"><div className="demo-photo"><span>v.</span><small>FIND YOUR VIBE</small></div><div className="demo-caption"><div><b>{t('Новые люди','New people','Neue Menschen')}</b><small>{t('Похожие интересы. Новые истории.','Shared interests. New stories.','Gemeinsame Interessen. Neue Geschichten.')}</small></div><span className="demo-heart"><Heart size={20}/></span></div></div><span className="float-note float-one"><Heart size={15}/> {t('Взаимная симпатия','Mutual interest','Gegenseitige Sympathie')}</span><span className="float-note float-two"><Sparkles size={15}/> {t('Общие интересы','Shared interests','Gemeinsame Interessen')}</span></div></section><section className="landing-features"><article><span><Compass size={20}/></span><h3>{t('Открывай','Discover','Entdecken')}</h3><p>{t('Находи людей по интересам и знакомься с их историями.','Discover people by interests and learn their stories.','Entdecke Menschen mit ähnlichen Interessen und lerne ihre Geschichten kennen.')}</p></article><article><span><Heart size={20}/></span><h3>{t('Совпадай','Connect','Finde Gemeinsamkeiten')}</h3><p>{t('Отмечай симпатию и узнавай, когда интерес взаимный.','Show interest and find out when it is mutual.','Zeige Interesse und erfahre, wenn es erwidert wird.')}</p></article><article><span><MessageCircle size={20}/></span><h3>{t('Общайся','Chat','Kommuniziere')}</h3><p>{t('Начинай разговоры с уважением и без лишнего давления.','Start conversations with respect and without pressure.','Beginne Gespräche respektvoll und ohne Druck.')}</p></article></section><footer>vibe. © 2026 <span>{t('Твои люди. Твой ритм.','Your people. Your rhythm.','Deine Leute. Dein Rhythmus.')}</span><a className="support-email-link" href="mailto:vibesupport2026@gmail.com">{t('Поддержка','Support','Support')}: vibesupport2026@gmail.com</a></footer></main>}

function LegalPage(){
 const privacy=window.location.pathname.replace(/\/+$/,'')==='/privacy';
 const [lang,setLang]=useState(()=>{try{return localStorage.getItem('vibe-language')||'en'}catch{return 'en'}});
 const content={
  ru:{
   rulesTitle:'Правила сообщества VIBE',privacyTitle:'Политика конфиденциальности VIBE',
   rulesIntro:'VIBE создан для безопасного общения и знакомств по интересам. Используя сервис, ты соглашаешься соблюдать эти правила.',
   rules:[['Возраст и разделение','Сервис предназначен для пользователей от 14 лет. Пользователи 14–17 лет и 18+ находятся в отдельных группах; не пытайся обходить это разделение.'],['Уважение','Запрещены травля, угрозы, преследование, ненависть, шантаж и нежелательные сексуальные сообщения. Уважай отказ и личные границы.'],['Честные анкеты','Не выдавай себя за другого человека, не используй чужие фото без разрешения и не публикуй вводящую в заблуждение информацию.'],['Безопасность и личные данные','Не публикуй адрес, документы, пароли, финансовые данные или чужую переписку без согласия. Не проси несовершеннолетних о сексуальных изображениях.'],['Жалобы и меры','Используй функцию жалобы при нарушениях. Команда может проверять сообщения и анкеты и ограничивать доступ к сервису при нарушении правил.']],
   privacyIntro:'Здесь кратко объясняется, какие данные могут обрабатываться при использовании VIBE и как связаться с командой по вопросам приватности.',
   privacy:[['Данные, которые ты предоставляешь','Это могут быть сведения анкеты, дата рождения или возрастная категория, интересы, фотографии и другой контент, который ты отправляешь.'],['Данные сервиса','Для работы и защиты сервиса могут обрабатываться идентификатор аккаунта, технические данные, настройки, обращения в поддержку и жалобы, а также сведения о безопасности и нарушениях. При входе через Telegram сервис может получать Telegram user ID и доступные Telegram данные профиля.'],['Использование данных','Данные используются для работы функций VIBE, отображения анкет, общения, модерации, обработки жалоб, защиты от злоупотреблений и ответа на запросы поддержки.'],['Хранение и доступ','Не публикуй в анкете секретные или особо чувствительные сведения. Доступ к жалобам и данным модерации должен быть ограничен уполномоченной командой. Сроки хранения зависят от типа данных и требований безопасности.'],['Твои запросы','Чтобы запросить помощь по приватности, доступу или удалению данных, напиши на vibesupport2026@gmail.com. Для безопасности команда может попросить подтвердить, что аккаунт принадлежит тебе.']],
   note:''
  },
  en:{
   rulesTitle:'VIBE Community Rules',privacyTitle:'VIBE Privacy Policy',rulesIntro:'VIBE is designed for safer, interest-based conversations. By using the service, you agree to follow these rules.',
   rules:[['Age and separation','The service is for people aged 14 and over. Users aged 14–17 and 18+ are kept in separate groups. Do not try to bypass this separation.'],['Respect','Bullying, threats, stalking, hate, blackmail and unwanted sexual messages are prohibited. Respect refusals and boundaries.'],['Authentic profiles','Do not impersonate others, use someone else’s photos without permission, or post misleading information.'],['Safety and personal data','Do not publish addresses, identity documents, passwords, financial details or private conversations without consent. Never ask minors for sexual images.'],['Reports and enforcement','Use reporting tools for violations. The team may review profiles and reports and restrict access when rules are broken.']],
   privacyIntro:'This page explains, at a high level, what information may be processed when using VIBE and how to contact the team about privacy.',
   privacy:[['Information you provide','This may include profile details, birth date or age group, interests, photos and other content you submit.'],['Service data','For operation and safety, the service may process account identifiers, technical data, settings, support requests, reports and security-related information. Telegram sign-in may provide your Telegram user ID and available profile information.'],['How information is used','Information supports VIBE features, profile display, messaging, moderation, reports, abuse prevention and support.'],['Storage and access','Avoid posting secrets or highly sensitive information in your profile. Access to reports and moderation data should be limited to authorized staff. Retention periods depend on data type and safety needs.'],['Your requests','For privacy, access or deletion requests, email vibesupport2026@gmail.com. The team may ask you to verify account ownership.']],
   note:'This is an informational service page, not legal advice. Before public launch, the VIBE operator should provide legally accurate controller details, retention periods, processing grounds and applicable user rights.'
  },
  de:{
   rulesTitle:'VIBE-Gemeinschaftsregeln',privacyTitle:'VIBE-Datenschutzerklärung',rulesIntro:'VIBE soll sichere Gespräche und Kontakte über gemeinsame Interessen ermöglichen. Bei der Nutzung gelten diese Regeln.',
   rules:[['Alter und Trennung','Der Dienst ist für Personen ab 14 Jahren vorgesehen. Nutzer von 14–17 Jahren und Erwachsene ab 18 Jahren bleiben in getrennten Bereichen. Umgehe diese Trennung nicht.'],['Respekt','Mobbing, Drohungen, Nachstellen, Hass, Erpressung und unerwünschte sexuelle Nachrichten sind verboten. Respektiere Grenzen und ein Nein.'],['Echte Profile','Gib dich nicht als andere Person aus und verwende fremde Fotos nicht ohne Erlaubnis. Veröffentliche keine irreführenden Angaben.'],['Sicherheit und persönliche Daten','Veröffentliche keine Adressen, Ausweisdokumente, Passwörter, Finanzdaten oder private Nachrichten ohne Zustimmung. Fordere Minderjährige niemals zu sexuellen Bildern auf.'],['Meldungen','Melde Verstöße über die Meldefunktion. Das Team kann Profile und Meldungen prüfen und bei Regelverstößen den Zugang beschränken.']],
   privacyIntro:'Hier steht eine allgemeine Übersicht über Daten, die bei der Nutzung von VIBE verarbeitet werden können, sowie der Kontakt für Datenschutzanfragen.',
   privacy:[['Von dir bereitgestellte Angaben','Dazu können Profilangaben, Geburtsdatum oder Altersgruppe, Interessen, Fotos und andere von dir übermittelte Inhalte gehören.'],['Dienstbezogene Daten','Für Betrieb und Sicherheit können Konto-IDs, technische Daten, Einstellungen, Supportanfragen, Meldungen und sicherheitsbezogene Informationen verarbeitet werden. Bei Telegram-Anmeldung kann VIBE deine Telegram-user-ID und verfügbare Profildaten erhalten.'],['Verwendung','Die Daten dienen den VIBE-Funktionen, der Profilanzeige, Kommunikation, Moderation, Bearbeitung von Meldungen, Missbrauchsvermeidung und dem Support.'],['Speicherung und Zugriff','Veröffentliche keine Geheimnisse oder besonders sensiblen Angaben im Profil. Zugriff auf Meldungen und Moderationsdaten sollte auf autorisierte Teammitglieder beschränkt sein. Aufbewahrungsfristen hängen von Datentyp und Sicherheitsbedarf ab.'],['Deine Anfragen','Für Datenschutz-, Auskunfts- oder Löschanfragen schreibe an vibesupport2026@gmail.com. Zur Sicherheit kann ein Nachweis der Kontoinhaberschaft erforderlich sein.']],
   note:'Diese Informationsseite ist keine Rechtsberatung. Vor dem öffentlichen Start sollte der Betreiber von VIBE rechtlich korrekte Angaben zum Verantwortlichen, zu Speicherfristen, Rechtsgrundlagen und Nutzerrechten ergänzen.'
  }
 };
 const c=content[lang]||content.ru;
 const sections=privacy?c.privacy:c.rules;
 return <main style={{minHeight:'100vh',background:'#100d19',color:'#f5f0ff',padding:'28px 18px 48px',fontFamily:'system-ui,sans-serif',boxSizing:'border-box'}}><article style={{maxWidth:760,margin:'0 auto'}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12}}><a href="/" style={{color:'#e5a6ff',textDecoration:'none',fontWeight:800,letterSpacing:'.04em'}}>vibe.</a><select aria-label="Language" value={lang} onChange={e=>{setLang(e.target.value);try{localStorage.setItem('vibe-language',e.target.value)}catch{}}} style={{background:'#211a2c',color:'#f5f0ff',border:'1px solid #493653',borderRadius:10,padding:'9px 12px'}}><option value="en">English</option><option value="de">Deutsch</option><option value="ru">Русский</option></select></div><p style={{color:'#c5b6d8',marginTop:28,fontSize:12,letterSpacing:'.12em',textTransform:'uppercase'}}>VIBE · {privacy?'PRIVACY':'COMMUNITY'}</p><h1 style={{fontSize:'clamp(30px,6vw,44px)',lineHeight:1.1,margin:'8px 0 18px'}}>{privacy?c.privacyTitle:c.rulesTitle}</h1><p style={{color:'#d8cfe5',lineHeight:1.7,fontSize:17}}>{privacy?c.privacyIntro:c.rulesIntro}</p><div style={{display:'grid',gap:18,marginTop:28}}>{sections.map(([title,body],i)=><section key={title} style={{border:'1px solid #352844',borderRadius:18,padding:20,background:'#171220'}}><h2 style={{fontSize:19,margin:'0 0 8px'}}>{i+1}. {title}</h2><p style={{color:'#d2c8df',lineHeight:1.7,margin:0}}>{body}</p></section>)}</div>{privacy&&<p style={{fontSize:13,color:'#a99bb8',lineHeight:1.7,marginTop:22}}>{c.note}</p>}<footer style={{borderTop:'1px solid #352844',marginTop:30,paddingTop:20,color:'#b9abc9',fontSize:14}}>VIBE © 2026 · <a style={{color:'#e5a6ff'}} href="mailto:vibesupport2026@gmail.com">vibesupport2026@gmail.com</a><p style={{marginBottom:0}}><a style={{color:'#e5a6ff'}} href={privacy?'/rules':'/privacy'}>{privacy?c.rulesTitle:c.privacyTitle}</a></p></footer></article></main>;
}

const legalPath=['/rules','/privacy'].includes(window.location.pathname.replace(/\/+$/,'')||'/');
createRoot(document.getElementById('root')).render(legalPath?<LegalPage/>:<App/>);
